shek=c('shekhem','10a:3','אמר אביי בשכם נמי שכיחי רוצחים דכתיב (הושע ו, ט) וכחכי איש גדודים חבר כהנים דרך ירצחו שכמה וגו\'','Abaye says killers are also prevalent in Shekhem and cites Hosea.',voice='אביי');e('shekhem.answer',shek,distq,'answer','10a:3','בשכם נמי שכיחי רוצחים')
