sub=c('suburbs','10a:5','אמר אביי פרוודהא דכתיב (יהושע כא, יב) ואת שדה העיר ואת חצריה נתנו לכלב בן יפנה','Abaye answers that Caleb received the outlying fields and villages, as Joshua specifies.',voice='אביי');e('suburbs.answer',sub,heq,'answer','10a:5','פרוודהא')
